```sql
/* Подсчёт общего числа атомов в молекулах, содержащих тройную связь и атомы фосфора или брома */
SELECT COUNT(DISTINCT a."atom_id") AS total_atoms
FROM "atom" a
JOIN "molecule" m ON a."molecule_id" = m."molecule_id"
WHERE a."molecule_id" IN (
    /* Молекулы с тройной связью */
    SELECT b."molecule_id"
    FROM "bond" b
    WHERE b."bond_type" = '#'
)
AND a."molecule_id" IN (
    /* Молекулы, содержащие фосфор или бром */
    SELECT a2."molecule_id"
    FROM "atom" a2
    WHERE LOWER(a2."element") IN ('p', 'br')
);
```

```sql
/* Вычисляем долю канцерогенных молекул (label = '+'), содержащих атом хлора (element = 'cl') */
SELECT
    /* Процент = число канцерогенных молекул с хлором / общее число молекул */
    SUM(CASE WHEN m."label" = '+' AND a."element" = 'cl' THEN 1 ELSE 0 END)::numeric
    / COUNT(DISTINCT m."molecule_id") AS percentage
FROM "molecule" m
LEFT JOIN "atom" a
    ON a."molecule_id" = m."molecule_id";
```

```sql
/* Вычисляем процент молекул, содержащих водород (element = 'h') и являющихся канцерогенными (label = '+') */
SELECT
    /* Процент = (число молекул с водородом и label='+') / (общее число молекул) * 100 */
    (COUNT(DISTINCT CASE WHEN a."element" = 'h' AND m."label" = '+' THEN m."molecule_id" END)::numeric
     / NULLIF(COUNT(DISTINCT m."molecule_id"), 0)) * 100.0 AS percentage
FROM "molecule" m
LEFT JOIN "atom" a
    ON a."molecule_id" = m."molecule_id";
```

