```sql
/* Доля карт Story Spotlight без текстового блока (istextless = 0) от общего числа карт */
SELECT
    /* Процент: карты Story Spotlight без текста / все карты * 100 */
    (SUM(CASE WHEN c."isstoryspotlight" = 1 AND c."istextless" = 0 THEN 1 ELSE 0 END)::numeric
     / NULLIF(COUNT(c."id"), 0)) * 100 AS percentage,
    /* Список ID таких карт */
    STRING_AGG(
        CASE WHEN c."isstoryspotlight" = 1 AND c."istextless" = 0
             THEN c."id"::text END, ', '
    ) AS story_spotlight_textless_ids
FROM "cards" c;
```

```sql
/* Процент карт, доступных только в non-foil, среди сетов с японским переводом */
SELECT
    /* Доля сетов с isNonFoilOnly = 1 среди сетов, имеющих японский перевод */
    SUM(CASE WHEN s."isnonfoilonly" = 1 THEN 1 ELSE 0 END)::numeric
    / NULLIF(COUNT(*), 0) * 100 AS percentage_nonfoil_only
FROM "sets" s
WHERE s."code" IN (
    /* Сеты, у которых есть японский перевод */
    SELECT st."setcode"
    FROM "set_translations" st
    WHERE st."language" = 'Japanese'
);
