```sql
/* Доля карт без силы (power IS NULL или '*') на французском языке среди всех карт без силы */
SELECT
    /* Процент: французские карты без силы / все карты без силы * 100 */
    (COUNT(*) FILTER (WHERE fd."language" = 'French')::numeric
     / NULLIF(COUNT(*), 0)::numeric) * 100 AS percentage
FROM "foreign_data" fd
WHERE fd."power" IS NULL OR fd."power" = '*';
```

```sql
/* Вычисляем процент карт с французским языком среди карт Story Spotlight */
